interface ArrayIndexable<T> {
    readonly [index: number]: T;
}
interface DependencyMap extends ArrayIndexable<ModuleID> {
    paths?: Record<ModuleID, string>;
}
interface InverseDependencyMap {
    [key: string]: ModuleID[];
}
type Exports = any;
interface FactoryFn {
    (global: any, require: RequireFn, metroImportDefault: RequireFn, metroImportAll: RequireFn, moduleObject: Module, exports: any, dependencyMap?: DependencyMap): void;
}
type HotModuleReloadingCallback = () => void;
interface HotModuleReloadingData {
    _acceptCallback?: HotModuleReloadingCallback | null;
    _disposeCallback?: HotModuleReloadingCallback | null;
    _didAccept: boolean;
    accept(callback?: HotModuleReloadingCallback): void;
    dispose(callback?: HotModuleReloadingCallback): void;
}
type ModuleID = string | number;
interface Module {
    id?: ModuleID;
    exports: Exports;
    hot?: HotModuleReloadingData;
}
export interface RequireFn {
    (id: ModuleID | VerboseModuleNameForDev, moduleIdHint?: string): Exports;
    Refresh?: any;
    Systrace?: any;
}
export type DefineFn = (factory: FactoryFn, moduleId: number, dependencyMap?: DependencyMap, verboseName?: string, inverseDependencies?: InverseDependencyMap) => void;
type VerboseModuleNameForDev = string;
export {};
